#'   `xaxis.uirevision="time"` and `yaxis.uirevision="cost"`. Then if only
#'   the y data is changed, you can update `yaxis.uirevision="quantity"`
#'   and the y axis range will reset but the x axis range will retain any
#'   user-driven zoom. Any value.
#' @param uniformtext A \code{\link{go_uniformtext}()} object or named
#'   list, with properties \code{minsize} and \code{mode} (see
#'   \code{\link{go_uniformtext}()}).
#' @param updatemenus List, each element a \code{\link{go_updatemenu}()}
#'   object or named list, with properties \code{active}, \code{bgcolor},
#'   \code{bordercolor}, \code{borderwidth}, \code{buttons},
#'   \code{direction}, \code{font}, \code{name}, \code{pad},
#'   \code{showactive}, \code{templateitemname}, \code{type} and 5 more
#'   (see \code{\link{go_updatemenu}()}).
#' @param violingap Sets the gap (in plot fraction) between violins of
#'   adjacent location coordinates. Has no effect on traces that have
#'   "width" set. Number in the interval [0, 1].
#' @param violingroupgap Sets the gap (in plot fraction) between violins of
#'   the same location coordinate. Has no effect on traces that have
#'   "width" set. Number in the interval [0, 1].
#' @param violinmode Determines how violins at the same location coordinate
#'   are displayed on the graph. If "group", the violins are plotted next
#'   to one another centered around the shared location. If "overlay", the
#'   violins are plotted over one another, you might need to set "opacity"
#'   to see them multiple violins. Has no effect on traces that have
#'   "width" set. One of \code{"group"}, \code{"overlay"}.
#' @param waterfallgap Sets the gap (in plot fraction) between bars of
#'   adjacent location coordinates. Number in the interval [0, 1].
#' @param waterfallgroupgap Sets the gap (in plot fraction) between bars of
#'   the same location coordinate. Number in the interval [0, 1].
#' @param waterfallmode Determines how bars at the same location coordinate
#'   are displayed on the graph. With "group", the bars are plotted next to
#'   one another centered around the shared location. With "overlay", the
#'   bars are plotted over one another, you might need to reduce "opacity"
#'   to see multiple bars. One of \code{"group"}, \code{"overlay"}.
#' @param width Sets the plot's width (in px). Number in the interval [10,
#'   Inf].
#' @param xaxis A \code{\link{go_xaxis}()} object or named list, with
#'   properties \code{anchor}, \code{automargin}, \code{autorange},
#'   \code{autorangeoptions}, \code{autotickangles},
#'   \code{autotypenumbers}, \code{calendar}, \code{categoryarray},
#'   \code{categoryorder}, \code{color}, \code{constrain},
#'   \code{constraintoward} and 80 more (see \code{\link{go_xaxis}()}).
#' @param yaxis A \code{\link{go_yaxis}()} object or named list, with
#'   properties \code{anchor}, \code{automargin}, \code{autorange},
#'   \code{autorangeoptions}, \code{autoshift}, \code{autotickangles},
#'   \code{autotypenumbers}, \code{calendar}, \code{categoryarray},
#'   \code{categoryorder}, \code{color}, \code{constrain} and 80 more (see
#'   \code{\link{go_yaxis}()}).
#' @param ... Further properties, by their full names (e.g. numbered subplots
#'   such as \code{xaxis2} in \code{go_layout()}).
#' @param skip_invalid If \code{TRUE}, silently drop invalid properties
#'   instead of raising an error.
#' @return \code{go_*()} functions return a graph object;
#'   \code{add_*()} functions return the modified figure.
#' @seealso \code{\link{go_figure}()}, \code{\link{update_layout}()}
#'
#' @concept layout objects
#' @noMd
#' @export
#' @examples
#' go_layout(title = "My plot", xaxis = go_xaxis(title = "x", range = c(0, 10)))
go_layout <- function(
    arg = NULL, ..., activeselection = NULL, activeshape = NULL,
    annotations = NULL, autosize = NULL, autotypenumbers = NULL,
    barcornerradius = NULL, bargap = NULL, bargroupgap = NULL,
    barmode = NULL, barnorm = NULL, boxgap = NULL, boxgroupgap = NULL,
    boxmode = NULL, calendar = NULL, clickanywhere = NULL, clickmode = NULL,
    coloraxis = NULL, colorscale = NULL, colorway = NULL, computed = NULL,
    datarevision = NULL, dragmode = NULL, editrevision = NULL,
    extendfunnelareacolors = NULL, extendiciclecolors = NULL,
    extendpiecolors = NULL, extendsunburstcolors = NULL,
    extendtreemapcolors = NULL, font = NULL, funnelareacolorway = NULL,
    funnelgap = NULL, funnelgroupgap = NULL, funnelmode = NULL, geo = NULL,
    grid = NULL, height = NULL, hiddenlabels = NULL, hoveranywhere = NULL,
    hoverdistance = NULL, hoverlabel = NULL, hovermode = NULL,
    hoversort = NULL, hoversubplots = NULL, iciclecolorway = NULL,
    images = NULL, legend = NULL, map = NULL, margin = NULL, meta = NULL,
    minreducedheight = NULL, minreducedwidth = NULL, modebar = NULL,
    newselection = NULL, newshape = NULL, paper_bgcolor = NULL,
    piecolorway = NULL, plot_bgcolor = NULL, polar = NULL,
    scattergap = NULL, scattermode = NULL, scene = NULL,
    selectdirection = NULL, selectionrevision = NULL, selections = NULL,
    separators = NULL, shapes = NULL, showlegend = NULL, sliders = NULL,
    smith = NULL, spikedistance = NULL, sunburstcolorway = NULL,
    template = NULL, ternary = NULL, title = NULL, transition = NULL,
    treemapcolorway = NULL, uirevision = NULL, uniformtext = NULL,
    updatemenus = NULL, violingap = NULL, violingroupgap = NULL,
    violinmode = NULL, waterfallgap = NULL, waterfallgroupgap = NULL,
    waterfallmode = NULL, width = NULL, xaxis = NULL, yaxis = NULL,
    skip_invalid = FALSE
) {
  plotly_object("layout", arg, environment(), list(...), skip_invalid)
}

#' Layout activeselection objects
#'
#' The object for the figure layout's \code{activeselection}.
#' \code{go_activeselection()} creates one, with exactly its properties; a
#' named list with the same properties works too.
#'
#' @details
#' Nested objects are named lists, or objects of the constructors their
#' arguments name. Every property is checked against the plotly.js schema
#' when the object is created or modified. A property may be a one-sided
#' formula (\code{color = ~col}): it is kept, and evaluated in the data
#' (then checked) when its trace is added to a figure with
#' \code{add_<trace>()} or \code{add_trace()}.
#'
#' @param arg Optional named list, or graph object of the same type, to
#'   initialise properties from. Named arguments take precedence.
#' @param fillcolor Sets the color filling the active selection' interior.
#'   Color: a CSS color string or R color name.
#' @param opacity Sets the opacity of the active selection. Number in the
#'   interval [0, 1].
#' @param ... Not used: properties must be named in full.
#' @param skip_invalid If \code{TRUE}, silently drop invalid properties
#'   instead of raising an error.
#' @return A \code{go_layout_activeselection} object (a named list).
#'
#' @concept layout objects
#' @noMd
#' @export
#' @examples
#' go_figure() |>
#'   update_layout(
#'     activeselection = go_activeselection(opacity = 0.5)
#'   )
go_activeselection <- function(
    arg = NULL, ..., fillcolor = NULL, opacity = NULL, skip_invalid = FALSE
) {
  plotly_object("layout.activeselection", arg, environment(), list(...), skip_invalid)
}

